                    with self.subTest(
                        capacity=capacity,
                        budgets=budgets,
                        scenarios=scenarios,
                    ):
                        try:
                            frontier = scheme_frontier(capacity, budgets)
                        except ValueError:
                            continue
                        result = recommend_scheme_weighted_scenarios(
                            capacity, budgets, scenarios
