from itertools import product
from fractions import Fraction
from pqattest import scheme_frontier

# Work directly on the math: find any scenario multiset where a duplicate
# changes the winner vs the deduped tuple, on any frontier.
def normalised_rows(frontier):
    rows = [(c.sig_bytes, c.steps) for c in frontier]
    spans = tuple((min(r[i] for r in rows), max(r[i] for r in rows)) for i in range(2))
    return [tuple(Fraction(v-lo, hi-lo) if hi>lo else Fraction(0) for v,(lo,hi) in zip(row, spans)) for row in rows]

def winner_index(frontier, scenarios):
    norm = normalised_rows(frontier)
    totals = [sum(s) for s in scenarios]
    scores = [tuple(sum(w*c for w,c in zip(s,row))/t for s,t in zip(scenarios,totals)) for row in norm]
    best = [min(sc[i] for sc in scores) for i in range(len(scenarios))]
    def key(i):
        regrets = tuple(sc-b for sc,b in zip(scores[i], best))
        return (max(regrets), sum(regrets), scores[i])
    return min(range(len(frontier)), key=key)

weights = [(a,b) for a in range(0,6) for b in range(0,6) if a+b>0]
hits = 0
for capacity, budgets in ((1,(None,10**9)), (2,(None,10**9)), (16,(2300,9000)), (100,(None,8670))):
    try:
        frontier = scheme_frontier(capacity, budgets)
    except ValueError:
        continue
    for n in (2,3):
        for combo in product(weights, repeat=n):
            if len(set(combo)) != n:
                continue
            w0 = winner_index(frontier, combo)
            for dup in combo:
                if winner_index(frontier, combo+(dup,)) != w0:
                    print("HIT", capacity, budgets, combo, "dup", dup)
                    hits += 1
                    if hits > 3: raise SystemExit
print("done", hits)
